files.content:
:root {
  --bg: #1a1c2c;
  --card-bg: #f4f4f4;
  --text: #29366f;
  --accent: #ffcd75;
  --accent-dark: #ef7d57;
  --known: #38b764;
  --border: #566c86;
  --focus: #ffcd75;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: radial-gradient(circle at 20% 30%, #2a2d4a 0%, transparent 30%),
                    radial-gradient(circle at 80% 70%, #2a2d4a 0%, transparent 30%);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.app {
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

.title {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--accent);
  text-shadow: 3px 3px 0 #000;
  letter-spacing: 1px;
  text-align: center;
}

.deck {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.card {
  background: var(--card-bg);
  border: 6px solid var(--border);
  box-shadow: 6px 6px 0 #000;
  border-radius: 0;
  min-height: 200px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px;
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.1s;
  user-select: none;
  text-align: center;
  gap: 12px;
}

.card:hover {
  transform: translate(-2px, -2px);
  box-shadow: 8px 8px 0 #000;
}

.card:active {
  transform: translate(2px, 2px);
  box-shadow: 4px 4px 0 #000;
}

.card:focus-visible {
  outline: 4px solid var(--focus);
  outline-offset: 4px;
}

.card-content {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.3;
  word-break: break-word;
}

.card-hint {
  font-size: 0.875rem;
  color: var(--border);
  opacity: 0.8;
}

.controls, .actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  padding: 12px 20px;
  background: var(--accent);
  color: var(--text);
  border: 4px solid var(--border);
  box-shadow: 4px 4px 0 #000;
  border-radius: 0;
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.1s, background 0.1s;
  min-width: 100px;
}

.btn:hover {
  background: var(--accent-dark);
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 #000;
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 #000;
}

.btn:focus-visible {
  outline: 4px solid var(--focus);
  outline-offset: 2px;
}

.btn-accent {
  background: var(--known);
  color: #fff;
}

.btn-accent:hover {
  background: #2fa057;
}

.known-count {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
  white-space: nowrap;
}

@media (max-width: 400px) {
  .title {
    font-size: 1.4rem;
  }
  .card-content {
    font-size: 1.25rem;
  }
  .btn {
    min-width: 80px;
    padding: 10px 14px;
    font-size: 0.95rem;
  }
  .known-count {
    font-size: 1rem;
  }
}

const cards = [
  { word: 'Ephemeral', meaning: 'Lasting for a very short time.' },
  { word: 'Resilient', meaning: 'Able to recover quickly from difficulties.' },
  { word: 'Meticulous', meaning: 'Showing great attention to detail.' },
  { word: 'Ambiguous', meaning: 'Open to more than one interpretation.' },
  { word: 'Pragmatic', meaning: 'Dealing with things sensibly and realistically.' }
];

let currentIndex = 0;
let showingMeaning = false;
const knownSet = new Set();

const cardEl = document.getElementById('card');
const cardContent = document.getElementById('card-content');
const prevBtn = document.getElementById('prev-btn');
const nextBtn = document.getElementById('next-btn');
const gotItBtn = document.getElementById('got-it-btn');
const knownCountEl = document.getElementById('known-count');

function render() {
  const card = cards[currentIndex];
  cardContent.textContent = showingMeaning ? card.meaning : card.word;
  cardEl.setAttribute('aria-label', showingMeaning
    ? `Meaning: ${card.meaning}. Press Enter or Space to show word.`
    : `Word: ${card.word}. Press Enter or Space to show meaning.`);
  updateKnownCount();
}

function updateKnownCount() {
  knownCountEl.textContent = `Known: ${knownSet.size} / ${cards.length}`;
}

function flip() {
  showingMeaning = !showingMeaning;
  render();
}

function goTo(index) {
  currentIndex = (index + cards.length) % cards.length;
  showingMeaning = false;
  render();
}

cardEl.addEventListener('click', flip);
cardEl.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault();
    flip();
  }
});

prevBtn.addEventListener('click', () => goTo(currentIndex - 1));
nextBtn.addEventListener('click', () => goTo(currentIndex + 1));

gotItBtn.addEventListener('click', () => {
  knownSet.add(currentIndex);
  updateKnownCount();
  goTo(currentIndex + 1);
});

render();
